// ─── File: ThreadExplosionDemo.java ───
// Contrasts UNBOUNDED (explodes) vs BOUNDED (backpressure) thread usage.
// Each class below would be its own file in a real project.
package com.bank.threads;

import java.util.logging.*;

public class ThreadExplosionDemo {

    private static final Logger log = Logger.getLogger("Threads");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        int spikeRequests = 2000;             // festival-sale traffic spike

        int before = Thread.activeCount();
        log.info(() -> "Threads before spike = " + before);

        // ── BAD: a new unbounded executor per request against a slow partner ──
        UnboundedPaymentProcessor bad = new UnboundedPaymentProcessor();
        bad.handleSpike(spikeRequests);
        int peakBad = bad.peakThreads();
        log.severe(() -> "BAD path peak threads = " + peakBad
                + "  ← thousands spawned, CPU burns on context switching, 'add servers' only multiplies this");
        bad.shutdown();

        Thread.sleep(500);

        // ── GOOD: one shared bounded pool, bounded queue, timeouts, fail fast ──
        BoundedPaymentProcessor good = new BoundedPaymentProcessor();
        good.handleSpike(spikeRequests);
        log.info(() -> "GOOD path peak threads = " + good.peakThreads()
                + ", rejected (backpressure) = " + good.rejected()
                + "  ← bounded: constant threads, overload fails fast instead of exploding");
        good.shutdown();
    }
}

// ─── bad/UnboundedPaymentProcessor.java ───
// ANTI-PATTERN: new executor per request + cached (unbounded) pool.
class UnboundedPaymentProcessor {
    private static final Logger log = Logger.getLogger("Threads");
    private volatile int peak = 0;
    private final java.util.List<java.util.concurrent.ExecutorService> leaked = new java.util.ArrayList<>();

    void handleSpike(int requests) throws InterruptedException {
        for (int i = 0; i < requests; i++) {
            // BUG 1: a brand-new executor for EVERY request, never reused
            var ex = java.util.concurrent.Executors.newCachedThreadPool(); // BUG 2: unbounded
            leaked.add(ex);
            ex.submit(this::callSlowPartner);                              // blocks → more threads spawn
            peak = Math.max(peak, Thread.activeCount());
            if (i % 500 == 0) { int p = peak; log.warning(() -> "spawned... activeThreads≈" + p); }
        }
        Thread.sleep(300);
    }
    private void callSlowPartner() {
        try { Thread.sleep(800); } catch (InterruptedException ignored) {}  // slow partner bank
    }
    int peakThreads() { return peak; }
    void shutdown() { leaked.forEach(java.util.concurrent.ExecutorService::shutdownNow); }
}

// ─── good/BoundedPaymentProcessor.java ───
// CORRECT: one shared bounded pool + bounded queue + fail-fast rejection + timeout.
class BoundedPaymentProcessor {
    private static final Logger log = Logger.getLogger("Threads");
    private final java.util.concurrent.ThreadPoolExecutor pool;
    private final java.util.concurrent.atomic.AtomicInteger rejected = new java.util.concurrent.atomic.AtomicInteger();
    private volatile int peak = 0;

    BoundedPaymentProcessor() {
        this.pool = new java.util.concurrent.ThreadPoolExecutor(
                20, 50,                                   // core, max — sized to partner capacity
                30, java.util.concurrent.TimeUnit.SECONDS,
                new java.util.concurrent.ArrayBlockingQueue<>(200),  // bounded queue
                new java.util.concurrent.ThreadPoolExecutor.AbortPolicy()); // fail fast
    }

    void handleSpike(int requests) {
        for (int i = 0; i < requests; i++) {
            try {
                pool.submit(this::callSlowPartner);        // reused pool, no new threads beyond max
            } catch (java.util.concurrent.RejectedExecutionException e) {
                rejected.incrementAndGet();                // backpressure: overload rejected, not piled up
            }
            peak = Math.max(peak, pool.getPoolSize());
        }
    }
    private void callSlowPartner() {
        try { Thread.sleep(800); } catch (InterruptedException ignored) {} // same slow partner
    }
    int peakThreads() { return peak; }
    int rejected() { return rejected.get(); }
    void shutdown() { pool.shutdownNow(); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
